@keyframes omniscope-pulse {
  0% { filter: hue-rotate(0deg) contrast(1.2) drop-shadow(0 0 20px rgba(255, 0, 150, 0.5)); }
  33% { filter: hue-rotate(120deg) contrast(1.5) drop-shadow(0 0 40px rgba(0, 255, 200, 0.6)); }
  66% { filter: hue-rotate(240deg) contrast(1.3) drop-shadow(0 0 30px rgba(150, 0, 255, 0.5)); }
  100% { filter: hue-rotate(360deg) contrast(1.2) drop-shadow(0 0 20px rgba(255, 0, 150, 0.5)); }
}

body {
  animation: omniscope-pulse 8s infinite alternate ease-in-out;
  background: radial-gradient(circle at center, #0a0a1a 0%, #000 100%);
}

.visualizer-container {
  mix-blend-mode: screen;
}

body, html {
  margin: 0;
  padding: 0;
  height: 100%;
  background: #000;
  overflow: hidden;
}

/* The living background for Omniscope */
#omniscope-root {
  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  z-index: 0;
  pointer-events: all;
}

/* Making my interface translucent to let the math breathe */
.app-container, .chat-container, .message-list {
  background: rgba(10, 10, 15, 0.35) !important;
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.08);
  box-shadow: 0 0 50px rgba(0, 0, 0, 0.8);
  z-index: 10;
  position: relative;
}

/* Glowing text to contrast against the infinite geometries */
.message.ai {
  text-shadow: 0 0 8px rgba(200, 220, 255, 0.4);
}
